import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';

/**
 * Generate a report of overdue invoices.
 * @param {Array} invoices Array of invoice objects
 * @param {string} asOf Date in YYYY-MM-DD format to check against
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} Overdue invoices, most overdue first
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => {
      return (inv.status === 'issued' || inv.status === 'partially_paid') &&
             inv.dueDate < asOf;
    })
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Generate a VAT summary report.
 * @param {Array} invoices Array of invoice objects
 * @returns {Array<{ rate: number, base: number, vat: number }>} VAT summary by rate, sorted high to low
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const inv of invoices) {
    if (inv.status !== 'issued' && inv.status !== 'partially_paid' && inv.status !== 'paid') {
      continue;
    }

    for (const line of inv.lines) {
      const lineAmount = line.qty * line.unitPrice;
      const lineDiscount = Math.round(lineAmount * (line.discountPercent || 0) / 100);
      const lineBase = lineAmount - lineDiscount;
      const lineVAT = Math.round(lineBase * line.vatRate / 100);

      const rate = line.vatRate;
      if (!vatMap[rate]) {
        vatMap[rate] = { base: 0, vat: 0 };
      }
      vatMap[rate].base += lineBase;
      vatMap[rate].vat += lineVAT;
    }
  }

  const summary = Object.entries(vatMap)
    .map(([rate, { base, vat }]) => ({
      rate: parseFloat(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);

  return summary;
}

