test('lateFee: fee on heavily discounted invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 50 }],
    terms: 'NET14',
  });
  assert(inv.ok);

  const invIssue = issueInvoice(inv.value, []);
  assert(invIssue.ok);

  const lineAmount = 5 * 9500;
  const discountedAmount = Math.round(lineAmount * 0.5);
  const base = discountedAmount;
  const vat = Math.round(base * 0.21);
  const due = discountedAmount + vat;

  const result = lateFee(invIssue.value, '2026-10-22');

  const expectedFee = Math.round(due * 0.0004 * 1);
  assert.equal(result, expectedFee);
});

test('lateFee: very large late fee calculation', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1000 }],
    terms: 'NET14',
